css:
.mixsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #2a1f2d;
    background: linear-gradient(160deg, #fdf2f4 0%, #f7eef6 100%);
    border-radius: 18px;
}

.mixsim-container * {
    box-sizing: border-box;
}

.mixsim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #2a1f2d 0%, #6e2a52 55%, #b5446e 100%);
    color: #fdeef4;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(110, 42, 82, 0.30);
}

.mixsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.mixsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #f4c8a0;
    background: rgba(255, 255, 255, 0.12);
    padding: 5px 14px;
    border-radius: 999px;
}

.mixsim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #f8dde8;
}

.mixsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #6e2a52;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.mixsim-period-counter #currentDay,
.mixsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #b5446e;
}

.mixsim-round-name {
    background: #f3d9e6;
    color: #6e2a52;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.mixsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a4a17;
    background: #fbe7d2;
    padding: 4px 12px;
    border-radius: 999px;
}

.mixsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.mixsim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #f0dbe5;
    box-shadow: 0 4px 14px rgba(110, 42, 82, 0.07);
    border-top: 4px solid #b5446e;
}

.mixsim-card-cpa { border-top-color: #2f7d6b; }
.mixsim-card-trust { border-top-color: #b5446e; }
.mixsim-card-conv { border-top-color: #c79a2b; }
.mixsim-card-incident { border-top-color: #8a6db0; }

.mixsim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #94778a;
}

.mixsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #6e2a52;
}

.mixsim-card-cpa .mixsim-value { color: #2f7d6b; }
.mixsim-card-trust .mixsim-value { color: #b5446e; }
.mixsim-card-conv .mixsim-value { color: #c79a2b; }
.mixsim-card-incident .mixsim-value { color: #8a6db0; }

.mixsim-sublabel {
    font-size: 0.76rem;
    color: #98818f;
    line-height: 1.35;
}

/* CPA: lower is better — green when on/under target, red when above */
.mixsim-cpa-target .mixsim-value { color: #2f7d6b; }
.mixsim-cpa-high .mixsim-value { color: #c0392b; }

/* Trust: green when recovered toward baseline, red when slipping */
.mixsim-trust-good .mixsim-value { color: #2f7d6b; }
.mixsim-trust-bad .mixsim-value { color: #c0392b; }

.mixsim-incident-danger { border-top-color: #c0392b; }
.mixsim-incident-danger .mixsim-value { color: #c0392b; }

.mixsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #2a1f2d;
    color: #fdeef4;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.mixsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #f4c8a0;
}

.mixsim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #b5446e;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(110, 42, 82, 0.05);
}

.mixsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.mixsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #6e2a52;
    margin-bottom: 6px;
}

.mixsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #4a3744;
}

.mixsim-briefing-text strong { color: #2f7d6b; }
.mixsim-briefing-text em { color: #9a4a17; font-style: italic; }

.mixsim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #f0dbe5;
    box-shadow: 0 4px 14px rgba(110, 42, 82, 0.07);
}

.mixsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #6e2a52;
    border-bottom: 2px solid #f3e4ec;
    padding-bottom: 8px;
}

.mixsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #4a2740;
    margin: 14px 0 6px;
}

.mixsim-container select,
.mixsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #e2c3d3;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fdf6f9;
    color: #2a1f2d;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.mixsim-container select:focus,
.mixsim-container input[type="number"]:focus {
    outline: none;
    border-color: #b5446e;
    box-shadow: 0 0 0 3px rgba(181, 68, 110, 0.15);
}

.mixsim-container select option {
    background-color: #ffffff;
    color: #2a1f2d;
}

.mixsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #b5446e;
}

.mixsim-range-readout,
.mixsim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #6e2a52;
    margin-top: 4px;
}

.mixsim-range-readout span:last-child,
.mixsim-alloc-readout span:nth-child(2) {
    color: #2f7d6b;
    font-weight: 800;
}

.mixsim-hint {
    font-size: 0.8rem;
    color: #98818f;
    margin-top: 4px;
    line-height: 1.4;
}

.mixsim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.mixsim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #fbeef4;
    border: 1px solid #f1d8e4;
    border-radius: 9px;
    padding: 8px 12px;
}

.mixsim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #4a2740;
}

.mixsim-alloc-row input[type="number"] {
    width: 90px;
    flex: 0 0 90px;
}

.mixsim-alloc-row select {
    width: 220px;
    flex: 0 0 220px;
}

.mixsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.mixsim-container .btn-primary {
    background: linear-gradient(135deg, #b5446e 0%, #6e2a52 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(181, 68, 110, 0.30);
}

.mixsim-container .btn-primary:hover {
    filter: brightness(1.07);
}

.mixsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #e2c3d3;
    color: #94778a;
}

.mixsim-coach {
    background: #2a1f2d;
    color: #fdeef4;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(42, 31, 45, 0.25);
}

.mixsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #e79bbf;
    margin-bottom: 8px;
}

.mixsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.mixsim-coach-body strong { color: #f4c8a0; }
.mixsim-coach-body em { color: #f0a7c4; font-style: italic; }

.mixsim-history,
.mixsim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #f0dbe5;
    box-shadow: 0 4px 14px rgba(110, 42, 82, 0.07);
}

.mixsim-history h3,
.mixsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #6e2a52;
}

.mixsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #4a2740;
}

.mixsim-container table#usfHistoryTable th {
    background: #fbeef4;
    color: #6e2a52;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #f1d8e4;
}

.mixsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f6e9f0;
}

.mixsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #fdf6f9;
}

.mixsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .mixsim-container {
        padding: 14px;
    }
    .mixsim-header h1 {
        font-size: 1.7rem;
    }
    .mixsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .mixsim-value {
        font-size: 2rem;
    }
    .mixsim-clock {
        margin-left: 0;
    }
    .mixsim-period-counter {
        font-size: 0.88rem;
    }
    .mixsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .mixsim-alloc-row {
        flex-wrap: wrap;
    }
    .mixsim-alloc-row input[type="number"],
    .mixsim-alloc-row select {
        width: 100%;
        flex: 1 1 100%;
    }
    .mixsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / debrief screen ---- */
.mixsim-completion { padding: 8px 4px 4px; }
.mixsim-cm-head { text-align: center; margin-bottom: 16px; }
.mixsim-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #2f7d6b; }
.mixsim-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #6e8f86; }
.mixsim-cm-grade { font-size: 1.2rem; font-weight: 700; margin-top: 6px; color: #2a1f2d; }
.mixsim-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.mixsim-cm-yes { background: rgba(47,125,107,0.15); color: #256a5a; border: 1px solid rgba(47,125,107,0.42); }
.mixsim-cm-no { background: rgba(181,68,110,0.12); color: #a13c62; border: 1px solid rgba(181,68,110,0.4); }
.mixsim-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.mixsim-cm-metric { flex: 1 1 120px; min-width: 108px; background: #f4faf8; border: 1px solid #cfe9e2; border-radius: 10px; padding: 10px 8px; text-align: center; }
.mixsim-cm-mv { display: block; font-size: 1.4rem; font-weight: 800; color: #2f7d6b; }
.mixsim-cm-ml { display: block; font-size: 0.72rem; margin-top: 4px; color: #6e8f86; text-transform: uppercase; letter-spacing: 0.03em; }
.mixsim-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #2a1f2d; }
.mixsim-cm-insights { margin: 0; padding-left: 20px; }
.mixsim-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #3a2f3d; }

