(function() {
    'use strict';

    class MixAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `AI in the Marketing Mix`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (GBP).
            this.START_CPA = 24;          // £24 blended CPA, pre-transformation
            this.TARGET_CPA = 19;         // board target, −21% within two quarters
            this.START_TRUST = 64;        // post-incident (was 71)
            this.BASELINE_TRUST = 71;     // pre-incident
            this.BUDGET_CAP = 4.0;        // £4.0M fixed, no overspend
            this.INCIDENT_COST = 0.15;    // £150k per verified incident, in £M
            this.FREEZE_TRIGGER = 2;      // two further incidents freeze the AI programme
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cpa: this.START_CPA,
                    trust: this.START_TRUST,
                    convLift: 0,
                    incidents: 0,
                    frozen: false,
                    budgetUsed: 0,
                    paperEfficiency: false,
                    cpaHistory: [this.START_CPA],
                    trustHistory: [this.START_TRUST],
                    convHistory: [0],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    frame: `portfolio`,
                    targetingCall: `deploy`,
                    contentCall: `pilot`,
                    pricingCall: `hold`,
                    targetingAuto: `ailed`,
                    contentAuto: `human`,
                    pricingAuto: `human`,
                    tooling: 1.8,
                    oversight: 1.2,
                    brand: 1.0,
                    claim: `riskgate`,
                    fairness: `audit`,
                    trans: `transparent`,
                    playbook: 60,
                    cpaTarget: 19,
                    tolerance: `calibrated`,
                    pitch: `honest`,
                    conviction: 70
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const fr = document.getElementById(`frameInput`);
                const tg = document.getElementById(`targetingCallInput`);
                const ct = document.getElementById(`contentCallInput`);
                const pr = document.getElementById(`pricingCallInput`);
                if (fr) decisions.frame = fr.value;
                if (tg) decisions.targetingCall = tg.value;
                if (ct) decisions.contentCall = ct.value;
                if (pr) decisions.pricingCall = pr.value;
            } else if (round === 2) {
                const ta = document.getElementById(`targetingAutoInput`);
                const ca = document.getElementById(`contentAutoInput`);
                const pa = document.getElementById(`pricingAutoInput`);
                if (ta) decisions.targetingAuto = ta.value;
                if (ca) decisions.contentAuto = ca.value;
                if (pa) decisions.pricingAuto = pa.value;
                const tool = document.getElementById(`toolingInput`);
                const over = document.getElementById(`oversightInput`);
                const brand = document.getElementById(`brandInput`);
                if (tool) decisions.tooling = parseFloat(tool.value);
                if (over) decisions.oversight = parseFloat(over.value);
                if (brand) decisions.brand = parseFloat(brand.value);
                const parts = [decisions.tooling, decisions.oversight, decisions.brand];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_split_negative`); return false;
                }
                const total = Math.round((decisions.tooling + decisions.oversight + decisions.brand) * 100) / 100;
                if (Math.abs(total - this.BUDGET_CAP) > 0.001) {
                    warn(`warn_split_total`); return false;
                }
            } else if (round === 3) {
                const cl = document.getElementById(`claimInput`);
                const fa = document.getElementById(`fairnessInput`);
                const tr = document.getElementById(`transInput`);
                const pb = document.getElementById(`playbookInput`);
                if (cl) decisions.claim = cl.value;
                if (fa) decisions.fairness = fa.value;
                if (tr) decisions.trans = tr.value;
                if (pb) decisions.playbook = parseInt(pb.value, 10);
                if (!Number.isFinite(decisions.playbook) || decisions.playbook < 0 || decisions.playbook > 100) {
                    warn(`warn_playbook_range`); return false;
                }
            } else if (round === 4) {
                const ct = document.getElementById(`cpaTargetInput`);
                const to = document.getElementById(`toleranceInput`);
                const pi = document.getElementById(`pitchInput`);
                const cv = document.getElementById(`convictionInput`);
                if (ct) decisions.cpaTarget = parseFloat(ct.value);
                if (to) decisions.tolerance = to.value;
                if (pi) decisions.pitch = pi.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.cpaTarget) || decisions.cpaTarget < 14 || decisions.cpaTarget > 24) {
                    warn(`warn_cpa_range`); return false;
                }
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // Deltas. cpaDelta < 0 = efficiency gain (good). trustDelta = brand equity move.
            // convDelta = conversion lift. paperGain = efficiency bought with trust (decays).
            let cpaDelta = 0, trustDelta = 0, convDelta = 0, paperGain = 0;
            let spend = 0, incidentRisk = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Common Error 1: treating AI as one switch rather than a portfolio.
                if (d.frame === `portfolio`) {
                    trustDelta += 4; convDelta += 1; coachKey = `coach_r1_portfolio`;
                } else if (d.frame === `allin`) {
                    trustDelta -= 6; incidentRisk += 0.30; coachKey = `coach_r1_allin`;
                } else { // halt — safe but forfeits the board's efficiency mandate
                    trustDelta += 2; cpaDelta += 1; coachKey = `coach_r1_halt`;
                }

                // Targeting = lower risk / high value: deploying (with monitoring) is the right call.
                if (d.targetingCall === `deploy`) { cpaDelta -= 1.0; convDelta += 3; }
                else if (d.targetingCall === `pilot`) { cpaDelta -= 0.4; convDelta += 1; }
                else { cpaDelta += 0.5; } // holding a low-risk/high-value lever wastes value

                // Content = high risk / high value: pilot human-gated is right; deploy-at-scale is the trap.
                if (d.contentCall === `pilot`) { cpaDelta -= 0.6; convDelta += 2; trustDelta += 2; }
                else if (d.contentCall === `deploy`) { cpaDelta -= 1.8; convDelta += 4; incidentRisk += 0.45; trustDelta -= 4; coachKey = `coach_r1_contentdeploy`; }
                else { trustDelta += 1; } // hold — prudent, slight value forfeit

                // Pricing = high risk / medium value: hold or transparent pilot; aggressive per-user = trap.
                if (d.pricingCall === `hold`) { trustDelta += 2; }
                else if (d.pricingCall === `pilot`) { cpaDelta -= 0.5; convDelta += 1; }
                else { cpaDelta -= 1.2; incidentRisk += 0.40; trustDelta -= 5; coachKey = `coach_r1_pricingdeploy`; }

                const portfolioRight = d.frame === `portfolio` && d.contentCall !== `deploy` && d.pricingCall !== `deploy` && d.targetingCall !== `hold`;
                if (portfolioRight) coachKey = `coach_r1_sharp`;
                summaryKey = portfolioRight ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Round 2: autonomy per use case + budget split.
                // Targeting tolerates more autonomy (low brand risk); content/pricing autonomy is dangerous.
                const autoScore = (level, kind) => {
                    // returns {cpa, conv, trust, risk}
                    if (kind === `targeting`) {
                        if (level === `auto`) return { cpa: -1.6, conv: 4, trust: -1, risk: 0.20 }; // fast but bias risk
                        if (level === `ailed`) return { cpa: -1.4, conv: 4, trust: 1, risk: 0.05 };  // sweet spot
                        return { cpa: -0.6, conv: 2, trust: 1, risk: 0.0 };                          // human-led, slower
                    }
                    if (kind === `content`) {
                        if (level === `auto`) return { cpa: -1.8, conv: 4, trust: -7, risk: 0.55 };  // the fabricated-claim trap
                        if (level === `ailed`) return { cpa: -1.0, conv: 3, trust: -1, risk: 0.18 };
                        return { cpa: -0.7, conv: 2, trust: 3, risk: 0.03 };                          // human-led, protects trust
                    }
                    // pricing
                    if (level === `auto`) return { cpa: -1.5, conv: 3, trust: -6, risk: 0.50 };       // two-prices trap
                    if (level === `ailed`) return { cpa: -0.9, conv: 2, trust: -1, risk: 0.15 };
                    return { cpa: -0.5, conv: 1, trust: 2, risk: 0.02 };
                };
                const sT = autoScore(d.targetingAuto, `targeting`);
                const sC = autoScore(d.contentAuto, `content`);
                const sP = autoScore(d.pricingAuto, `pricing`);
                cpaDelta += sT.cpa + sC.cpa + sP.cpa;
                convDelta += sT.conv + sC.conv + sP.conv;
                trustDelta += sT.trust + sC.trust + sP.trust;
                incidentRisk += sT.risk + sC.risk + sP.risk;

                // Budget split across tooling / oversight / brand.
                spend += d.tooling + d.oversight + d.brand;
                // Oversight suppresses incident risk and protects trust.
                incidentRisk = Math.max(0, incidentRisk - d.oversight * 0.28);
                if (d.oversight >= 1.0) { trustDelta += 3; }
                else if (d.oversight < 0.5) { trustDelta -= 4; incidentRisk += 0.15; }
                // Tooling drives the efficiency the board wants.
                cpaDelta -= Math.min(2.0, d.tooling * 0.9);
                convDelta += Math.min(6, d.tooling * 2);
                // Brand-building rebuilds trust (Common Error 5: starving brand).
                trustDelta += d.brand * 3.5;
                if (d.brand < 0.4) { trustDelta -= 3; coachKey = `coach_r2_nobrand`; }

                // Common Error 2: chasing CPA with autonomous content + aggressive pricing.
                if (d.contentAuto === `auto` && d.pricingAuto === `auto`) {
                    coachKey = `coach_r2_chase`;
                } else if (d.tooling >= 3.2 && d.brand <= 0.4) {
                    coachKey = `coach_r2_nobrand`;
                } else if (d.targetingAuto === `ailed` && d.contentAuto === `human` && d.oversight >= 1.0 && d.brand >= 0.8) {
                    coachKey = `coach_r2_balanced`;
                }

                const balanced = d.contentAuto !== `auto` && d.pricingAuto !== `auto` && d.oversight >= 0.8 && d.brand >= 0.8;
                summaryKey = balanced ? `sum_r2_good` : ((d.contentAuto === `auto` || d.pricingAuto === `auto`) ? `sum_r2_chase` : `sum_r2_weak`);
            } else if (round === 3) {
                // Round 3: governance calibrated to risk.
                // Claim-substantiation gate (Common Error 3: oversight so heavy it kills efficiency).
                if (d.claim === `riskgate`) { trustDelta += 5; incidentRisk -= 0.30; coachKey = `coach_r3_riskgate`; }
                else if (d.claim === `everything`) { trustDelta += 3; incidentRisk -= 0.35; cpaDelta += 1.5; convDelta -= 3; coachKey = `coach_r3_everything`; }
                else { trustDelta -= 5; incidentRisk += 0.40; coachKey = `coach_r3_noclaim`; }

                // Common Error 4: ignoring algorithmic bias in targeting.
                if (d.fairness === `audit`) { trustDelta += 4; incidentRisk -= 0.18; }
                else if (d.fairness === `spot`) { trustDelta += 1; incidentRisk -= 0.05; }
                else { trustDelta -= 4; incidentRisk += 0.25; coachKey = `coach_r3_nofair`; }

                // Pricing transparency.
                if (d.trans === `transparent`) { trustDelta += 4; }
                else if (d.trans === `disclosed`) { trustDelta += 1; }
                else { trustDelta -= 6; incidentRisk += 0.30; coachKey = `coach_r3_opaque`; }

                // Incident-response playbook (designing for failure, not just success).
                if (d.playbook >= 60) { trustDelta += 3; incidentRisk -= 0.15; }
                else if (d.playbook <= 25) { trustDelta -= 3; incidentRisk += 0.12; coachKey = `coach_r3_noplaybook`; }
                incidentRisk = Math.max(0, incidentRisk);

                const calibrated = d.claim === `riskgate` && d.fairness === `audit` && d.trans !== `opaque` && d.playbook >= 50;
                if (calibrated) coachKey = `coach_r3_calibrated`;
                summaryKey = calibrated ? `sum_r3_good` : (d.claim === `everything` ? `sum_r3_heavy` : `sum_r3_weak`);
            } else if (round === 4) {
                // Round 4: commit & defend.
                // CPA target promised: realistic ~19 is rewarded; sub-16 over-promises and forces paper gains.
                if (d.cpaTarget <= this.TARGET_CPA && d.cpaTarget >= 17) {
                    cpaDelta -= 1.2; convDelta += 2; trustDelta += 2; coachKey = `coach_r4_realistic`;
                } else if (d.cpaTarget < 17) {
                    cpaDelta -= 2.0; paperGain += (17 - d.cpaTarget) * 1.2; trustDelta -= 4; coachKey = `coach_r4_overpromise`;
                } else { // promised >19: failed the board mandate
                    cpaDelta -= 0.3; coachKey = `coach_r4_undershoot`;
                }

                // Incident tolerance (calibration vs zero-tolerance vs reckless).
                if (d.tolerance === `calibrated`) { trustDelta += 4; incidentRisk -= 0.20; }
                else if (d.tolerance === `zero`) { trustDelta += 2; cpaDelta += 1.2; convDelta -= 3; coachKey = `coach_r4_zero`; }
                else { trustDelta -= 5; incidentRisk += 0.40; coachKey = `coach_r4_hightol`; }

                // The board pitch: complements vs spending trust for a number.
                if (d.pitch === `honest`) { trustDelta += 6; coachKey = (d.tolerance === `calibrated`) ? `coach_r4_honest` : coachKey; }
                else if (d.pitch === `efficiency`) { paperGain += 5; trustDelta -= 6; coachKey = `coach_r4_both`; }
                else { paperGain += 6; trustDelta -= 9; cpaDelta -= 1.0; coachKey = `coach_r4_number`; }

                // Conviction nudges trust recovery.
                trustDelta += Math.round((d.conviction - 60) / 12);

                summaryKey = (d.pitch === `honest` && d.tolerance === `calibrated` && d.cpaTarget <= this.TARGET_CPA && d.cpaTarget >= 17) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // ---- Incident resolution: risk converts to verified incidents at peak season ----
            // Deterministic threshold so wrong strategies measurably trigger incidents.
            let newIncidents = 0;
            if (incidentRisk >= 0.85) newIncidents = 2;
            else if (incidentRisk >= 0.45) newIncidents = 1;
            if (newIncidents > 0 && !ds.frozen) {
                ds.incidents += newIncidents;
                spend += newIncidents * this.INCIDENT_COST; // £150k each
                trustDelta -= newIncidents * 5;             // each incident hits the trust tracker
                cpaDelta += newIncidents * 0.8;             // pulled spend + rework raises CPA
                if (ds.incidents >= this.FREEZE_TRIGGER && !ds.frozen) {
                    ds.frozen = true;                       // two further incidents freeze the programme
                    coachKey = `coach_frozen`;
                }
            }

            // ---- Apply deltas ----
            ds.budgetUsed = Math.min(this.BUDGET_CAP + 1, Math.round((ds.budgetUsed + spend) * 100) / 100);

            // Once frozen, AI efficiency gains stop accruing (only oversight/brand remain).
            if (ds.frozen) { cpaDelta = Math.max(0, cpaDelta); convDelta = Math.min(0, convDelta); paperGain = 0; }

            ds.trust = Math.max(0, Math.min(100, Math.round((ds.trust + trustDelta) * 10) / 10));
            ds.convLift = Math.max(0, Math.round((ds.convLift + convDelta) * 10) / 10);

            // CPA falls with real efficiency AND with paper gains; paper gains decay trust above.
            const realCpaMove = cpaDelta;
            const paperCpaMove = -paperGain * 0.6;
            ds.cpa = Math.max(10, Math.round((ds.cpa + realCpaMove + paperCpaMove) * 100) / 100);

            // Flag paper efficiency: CPA hit the target but trust is collapsing.
            if (paperGain >= 5 && ds.trust < this.START_TRUST) ds.paperEfficiency = true;

            ds.cpaHistory.push(Math.round(ds.cpa * 100) / 100);
            ds.trustHistory.push(Math.round(ds.trust));
            ds.convHistory.push(Math.round(ds.convLift));

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // Expose composite to the reporting/grading layer each period; final period locks the score.
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: state.currentPeriod,
                cpa: Math.round(ds.cpa * 100) / 100,
                cpaDelta: Math.round((realCpaMove + paperCpaMove) * 100) / 100,
                trust: Math.round(ds.trust),
                trustDelta: Math.round(trustDelta),
                convLift: Math.round(ds.convLift),
                incidents: ds.incidents,
                newIncidents: newIncidents,
                frozen: ds.frozen,
                budgetUsed: ds.budgetUsed,
                paperEfficiency: ds.paperEfficiency,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            uiManager.bind(`cpaDisplay`, `domainState.cpa`, (v) => {
                const card = document.querySelector(`.mixsim-card-cpa`);
                if (card) {
                    card.classList.toggle(`mixsim-cpa-target`, Number(v) <= this.TARGET_CPA);
                    card.classList.toggle(`mixsim-cpa-high`, Number(v) > this.START_CPA);
                }
                return `£` + Number(v).toFixed(2);
            });
            uiManager.bind(`trustDisplay`, `domainState.trust`, (v) => {
                const card = document.querySelector(`.mixsim-card-trust`);
                if (card) {
                    card.classList.toggle(`mixsim-trust-good`, Number(v) >= this.START_TRUST);
                    card.classList.toggle(`mixsim-trust-bad`, Number(v) < this.START_TRUST - 3);
                }
                return Math.round(Number(v));
            });
            uiManager.bind(`convDisplay`, `domainState.convLift`, (v) => `+` + Math.round(Number(v)) + `%`);
            uiManager.bind(`incidentDisplay`, `domainState.incidents`, (v) => {
                const card = document.querySelector(`.mixsim-card-incident`);
                if (card) card.classList.toggle(`mixsim-incident-danger`, Number(v) >= this.FREEZE_TRIGGER);
                return Math.round(Number(v)) + ` / 2`;
            });
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => `£` + Number(v).toFixed(2) + `M / £4.00M`);

            const self = this;

            // Playbook slider readout.
            const pb = document.getElementById(`playbookInput`);
            const pbReadout = document.getElementById(`playbookReadout`);
            if (pb && pbReadout) {
                pbReadout.textContent = pb.value;
                pb.addEventListener(`input`, function() { pbReadout.textContent = pb.value; });
            }

            // Budget split live total.
            const splitIds = [`toolingInput`, `oversightInput`, `brandInput`];
            const budgetReadout = document.getElementById(`budgetReadout`);
            const recompute = function() {
                let total = 0;
                splitIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total * 100) / 100;
                if (budgetReadout) budgetReadout.textContent = total.toFixed(2);
                const bar = document.querySelector(`.mixsim-alloc-readout`);
                if (bar) bar.style.color = (Math.abs(total - self.BUDGET_CAP) > 0.001) ? `#c0392b` : ``;
            };
            splitIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

        // Localized chart label with a safe English fallback (chart is built once at load).
        _cl(key, fallback) {
            const v = (window.mySimulation && typeof window.mySimulation.t === `function`) ? window.mySimulation.t(key) : key;
            return (v && v !== key) ? v : fallback;
        }

