        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.cpaHistory.map((_, i) => (i === 0 ? `Start` : `R` + i));
            return {
                mixChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.cpaHistory },
                        { data: ds.trustHistory },
                        { data: ds.convHistory }
                    ]
                }
            };
        }

        // Shared composite (0-100). Written to domainState.performance.overallScore each period for
        // the reporting/grading layer. Formula copied VERBATIM from v1.0.0 getPerformanceSummary.
        _composite(ds) {
            const cpa = Math.round((typeof ds.cpa === `number` ? ds.cpa : this.START_CPA) * 100) / 100;
            const trust = Math.round(ds.trust || 0);
            const convLift = Math.round(ds.convLift || 0);
            const cpaScore = Math.max(0, Math.min(100, (this.START_CPA - cpa) / (this.START_CPA - 14) * 100));
            let composite = Math.round(cpaScore * 0.30 + trust * 0.45 + Math.min(100, convLift * 4) * 0.25);
            if (ds.frozen) composite = Math.min(composite, 40);
            return Math.max(0, Math.min(100, composite));
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const cpa = Math.round(ds.cpa * 100) / 100;
            const trust = Math.round(ds.trust);
            const convLift = Math.round(ds.convLift);

            const hitCpa = cpa <= this.TARGET_CPA;
            const trustRecovered = trust >= this.BASELINE_TRUST;
            const trustHealthy = trust >= this.START_TRUST;
            const paper = ds.paperEfficiency || (hitCpa && trust < this.START_TRUST - 4);
            // Composite: single source of truth - identical value goes to domainState.performance.overallScore.
            const composite = this._composite(ds);

            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            let performanceKey = `grade_spent`;
            if (ds.frozen) performanceKey = `grade_frozen`;
            else if (hitCpa && trustRecovered && composite >= 72) performanceKey = `grade_leader`;
            else if (hitCpa && trustHealthy) performanceKey = `grade_trusted`;
            else if (hitCpa && paper) performanceKey = `grade_paper`;
            else if (hitCpa) performanceKey = `grade_bruised`;
            else if (trustRecovered) performanceKey = `grade_short_cpa`;
            else if (cpa < this.START_CPA - 2) performanceKey = `grade_improving`;
            const performance = T(performanceKey);

            const insights = [];
            if (ds.frozen) insights.push(window.mySimulation.t(`insight_frozen`));
            else if (hitCpa && trustRecovered) insights.push(window.mySimulation.t(`insight_leader`));
            else if (hitCpa && paper) insights.push(window.mySimulation.t(`insight_paper`));
            else if (hitCpa) insights.push(window.mySimulation.t(`insight_bruised`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (trust < this.START_TRUST) insights.push(window.mySimulation.t(`insight_trustfell`));
            if (ds.incidents >= 1 && !ds.frozen) insights.push(window.mySimulation.t(`insight_incident`));
            if (trustRecovered) insights.push(window.mySimulation.t(`insight_recovered`));
            if (hitCpa && trustRecovered && convLift >= 8) insights.push(window.mySimulation.t(`insight_complements`));

            return {
                cpa: cpa,
                trust: trust,
                convLift: convLift,
                incidents: ds.incidents,
                frozen: ds.frozen,
                hitCpa: hitCpa,
                paper: paper,
                composite: composite,
                totalScore: composite,
                overallScore: composite,
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        // v1.1.0: render the computed grade, KPIs and insight debrief in the completion modal
        // instead of the framework generic "you completed N periods" fallback.
        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            const s = summary || {};
            const score = (typeof s.totalScore === `number`) ? s.totalScore
                : (typeof s.composite === `number` ? s.composite : 0);
            const grade = s.performance || (s.performanceKey ? T(s.performanceKey) : ``);
            const met = !!s.hitCpa;
            const badge = met
                ? `<span class="mixsim-cm-badge mixsim-cm-yes">` + T(`cm_cpa_met`) + `</span>`
                : `<span class="mixsim-cm-badge mixsim-cm-no">` + T(`cm_cpa_missed`) + `</span>`;
            const frozenBadge = s.frozen
                ? ` <span class="mixsim-cm-badge mixsim-cm-no">` + T(`cm_frozen`) + `</span>`
                : ``;
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function(t) { return `<li>` + t + `</li>`; }).join(``);
            const cpaVal = (typeof s.cpa === `number`) ? (`\u00a3` + s.cpa.toFixed(2)) : `\u2014`;
            const metrics = ``
                + `<div class="mixsim-cm-metric"><span class="mixsim-cm-mv">` + cpaVal + `</span><span class="mixsim-cm-ml">` + T(`cm_m_cpa`) + `</span></div>`
                + `<div class="mixsim-cm-metric"><span class="mixsim-cm-mv">` + Math.round(s.trust || 0) + `</span><span class="mixsim-cm-ml">` + T(`cm_m_trust`) + `</span></div>`
                + `<div class="mixsim-cm-metric"><span class="mixsim-cm-mv">+` + Math.round(s.convLift || 0) + `%</span><span class="mixsim-cm-ml">` + T(`cm_m_conv`) + `</span></div>`
                + `<div class="mixsim-cm-metric"><span class="mixsim-cm-mv">` + Math.round(s.incidents || 0) + `</span><span class="mixsim-cm-ml">` + T(`cm_m_incidents`) + `</span></div>`;
            return ``
                + `<div class="mixsim-completion">`
                +   `<div class="mixsim-cm-head">`
                +     `<div class="mixsim-cm-score">` + score + `<span class="mixsim-cm-score-max">/100</span></div>`
                +     `<div class="mixsim-cm-grade">` + grade + ` ` + badge + frozenBadge + `</div>`
                +   `</div>`
                +   `<div class="mixsim-cm-metrics">` + metrics + `</div>`
                +   `<div class="mixsim-cm-insights-title">` + T(`cm_debrief`) + `</div>`
                +   `<ul class="mixsim-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.frozen) return window.mySimulation.t(`hint_frozen`);
            if (ds.paperEfficiency) return window.mySimulation.t(`hint_paper`);
            if (ds.incidents >= 1) return window.mySimulation.t(`hint_incident`);
            if (ds.trust < this.START_TRUST - 3) return window.mySimulation.t(`hint_trust`);
            if (state.currentPeriod >= 3 && ds.cpa > this.TARGET_CPA + 2) return window.mySimulation.t(`hint_cpa`);
            if (ds.cpa <= this.TARGET_CPA && ds.trust >= this.START_TRUST) return window.mySimulation.t(`hint_strong`);
            return null;
        }

